import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Settings, ChevronRight, User, ClipboardList, Heart, Target, Bell, Moon, Globe, LogOut, Key, Check, X, ShieldAlert } from 'lucide-react';
import AppLayout from '../components/AppLayout';
import { useApp } from '../context/AppContext';
import { apiLogout, apiUpdatePassword } from '../services/api';
import { C, BtnOrange } from '../components/UI';

function SettingsRow({ icon: Icon, label, value, onClick, danger, noBorder }) {
  return (
    <div 
      onClick={onClick} 
      style={{ 
        display:'flex', 
        alignItems:'center', 
        justifyContent:'space-between', 
        padding:'13px 0', 
        borderBottom: noBorder ? 'none' : `1px solid ${C.border}`, 
        cursor: onClick ? 'pointer':'default' 
      }}
    >
      <div style={{ display:'flex', alignItems:'center', gap:12 }}>
        <div style={{ width:32, height:32, borderRadius:8, background: danger ? 'rgba(255,77,109,0.1)':'#252525', display:'flex', alignItems:'center', justifyContent:'center' }}>
          <Icon size={16} color={danger ? '#ff4d6d':'#888'} />
        </div>
        <span style={{ fontSize:14, color: danger ? '#ff4d6d':'#e0e0e0' }}>{label}</span>
      </div>
      <div style={{ display:'flex', alignItems:'center', gap:8 }}>
        {value && <span style={{ fontSize:13, color:C.muted }}>{value}</span>}
        {!danger && <ChevronRight size={14} color="#444"/>}
      </div>
    </div>
  );
}

function Toggle({ on, onToggle }) {
  return (
    <div onClick={onToggle} style={{ width: 42, height: 24, borderRadius: 12, background: on ? C.orange : '#333', position: 'relative', cursor: 'pointer', transition: 'background 0.2s' }}>
      <div style={{ position: 'absolute', top: 3, left: on ? 21 : 3, width: 18, height: 18, borderRadius: '50%', background: '#fff', transition: 'left 0.2s' }} />
    </div>
  );
}

export default function ProfileScreen() {
  const navigate = useNavigate();
  const { user, setUser, darkMode, setDarkMode, savedFoodObjects } = useApp();
  const name = user?.name || 'Guest User';
  const email = user?.email || 'guest@nutribite.com';

  // ── States for interactive modals ───────────────────
  const [langModal, setLangModal] = useState(false);
  const [selectedLang, setSelectedLang] = useState('English');

  const [notifModal, setNotifModal] = useState(false);
  const [notifs, setNotifs] = useState({
    reminders: true,
    alerts: true,
    weekly: false,
  });

  const [pwdModal, setPwdModal] = useState(false);
  const [pwdForm, setPwdForm] = useState({ current: '', new: '', confirm: '' });
  const [pwdLoading, setPwdLoading] = useState(false);
  const [pwdToast, setPwdToast] = useState(null); // { type: 'success'|'error', msg }

  function handleLogout() {
    apiLogout();
    setUser(null);
    navigate('/onboarding');
  }

  // ── Password change submit ──────────────────────────
  async function handlePasswordChange(e) {
    e.preventDefault();
    setPwdToast(null);

    if (!pwdForm.current || !pwdForm.new || !pwdForm.confirm) {
      setPwdToast({ type: 'error', msg: 'All fields are required' });
      return;
    }
    if (pwdForm.new.length < 6) {
      setPwdToast({ type: 'error', msg: 'New password must be at least 6 characters' });
      return;
    }
    if (pwdForm.new !== pwdForm.confirm) {
      setPwdToast({ type: 'error', msg: 'Passwords do not match' });
      return;
    }

    try {
      setPwdLoading(true);
      await apiUpdatePassword({
        currentPassword: pwdForm.current,
        newPassword: pwdForm.new,
      });
      setPwdToast({ type: 'success', msg: 'Password updated successfully!' });
      setPwdForm({ current: '', new: '', confirm: '' });
      setTimeout(() => setPwdModal(false), 1200);
    } catch (err) {
      setPwdToast({ type: 'error', msg: err.message || 'Incorrect current password' });
    } finally {
      setPwdLoading(false);
    }
  }

  return (
    <AppLayout>
      <div style={{ padding: '20px 16px 0', position: 'relative' }}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h1 style={{ fontSize: 22, fontWeight: 800, color: '#fff', margin: 0 }}>Profile</h1>
          <button 
            onClick={() => setPwdModal(true)}
            style={{ background: 'rgba(255,255,255,0.04)', border: `1px solid ${C.border}`, borderRadius: 10, width: 38, height: 38, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#ccc', cursor: 'pointer', transition: 'background 0.2s' }}
          >
            <Settings size={18} />
          </button>
        </div>

        {/* Avatar card (clickable) */}
        <div 
          onClick={() => navigate('/personal-info')}
          style={{ display: 'flex', alignItems: 'center', gap: 14, background: '#1e1e1e', borderRadius: 16, padding: 16, border: `1px solid ${C.border}`, marginBottom: 24, cursor: 'pointer' }}
        >
          <div style={{ width: 52, height: 52, borderRadius: '50%', background: 'linear-gradient(135deg,#FF6B35,#FF8C5A)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, fontWeight: 800, color: '#fff', flexShrink: 0 }}>
            {name.charAt(0).toUpperCase()}
          </div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: 16, fontWeight: 700, color: '#fff' }}>{name}</div>
            <div style={{ fontSize: 12, color: C.muted }}>{email}</div>
          </div>
          <ChevronRight size={18} color="#444" />
        </div>

        {/* Stats row */}
        <div style={{ display: 'flex', gap: 10, marginBottom: 24 }}>
          {[
            { label: 'Saved Foods', value: savedFoodObjects.length, onClick: () => navigate('/favorites') },
            { label: 'Health Goals', value: user?.preferences?.healthGoals?.length || 0, onClick: () => navigate('/preferences') },
          ].map(stat => (
            <div 
              key={stat.label} 
              onClick={stat.onClick}
              style={{ flex: 1, background: '#1e1e1e', borderRadius: 12, padding: '12px 8px', textAlign: 'center', border: `1px solid ${C.border}`, cursor: 'pointer' }}
            >
              <div style={{ fontSize: 22, fontWeight: 800, color: C.orange }}>{stat.value}</div>
              <div style={{ fontSize: 10, color: C.muted, marginTop: 2 }}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Account Settings */}
        <p style={{ fontSize: 12, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 4 }}>Account</p>
        <div style={{ background: '#1e1e1e', borderRadius: 14, padding: '0 14px', border: `1px solid ${C.border}`, marginBottom: 20 }}>
          <SettingsRow icon={User} label="Personal Information" onClick={() => navigate('/personal-info')} value={user?.name ? user.name.split(' ')[0] : ''} />
          <SettingsRow icon={ClipboardList} label="Dietary Preferences" onClick={() => navigate('/preferences')} />
          <SettingsRow icon={Heart} label="Medical Reports" onClick={() => navigate('/medical-reports')} value={user?.medicalReports?.length ? `${user.medicalReports.length} Loaded` : ''} />
          <SettingsRow icon={Target} label="Health Goals" onClick={() => navigate('/preferences')} noBorder={true} />
        </div>

        {/* Preferences / App Settings */}
        <p style={{ fontSize: 12, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 4 }}>App Settings</p>
        <div style={{ background: '#1e1e1e', borderRadius: 14, padding: '0 14px', border: `1px solid ${C.border}`, marginBottom: 20 }}>
          <SettingsRow icon={Bell} label="Notifications" onClick={() => setNotifModal(true)} value={Object.values(notifs).filter(Boolean).length ? `${Object.values(notifs).filter(Boolean).length} Active` : 'Muted'} />

          {/* Dark Mode toggle inline */}
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 0', borderBottom: `1px solid ${C.border}` }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <div style={{ width: 32, height: 32, borderRadius: 8, background: '#252525', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Moon size={16} color="#888" /></div>
              <span style={{ fontSize: 14, color: '#e0e0e0' }}>Dark Mode</span>
            </div>
            <Toggle on={darkMode} onToggle={() => setDarkMode(v => !v)} />
          </div>

        </div>

        {/* Logout */}
        <div style={{ background: '#1e1e1e', borderRadius: 14, padding: '0 14px', border: `1px solid ${C.border}`, marginBottom: 16 }}>
          <div onClick={handleLogout} style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '14px 0', cursor: 'pointer', gap: 8 }}>
            <LogOut size={16} color="#ff4d6d" />
            <span style={{ color: '#ff4d6d', fontWeight: 700, fontSize: 14 }}>Log Out</span>
          </div>
        </div>

        <p style={{ textAlign: 'center', fontSize: 11, color: '#333', paddingBottom: 24, margin: 0 }}>Created by Sham</p>


        {/* ════════════════════════════════════════════════════
            MODAL 2: NOTIFICATIONS PREFERENCES
            ════════════════════════════════════════════════════ */}
        {notifModal && (
          <div className="phone-frame" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', zIndex: 2100, display: 'flex', alignItems: 'flex-end', paddingBottom: 'env(safe-area-inset-bottom)', paddingTop: 'env(safe-area-inset-top)' }}>
            <div style={{ background: '#171a20', width: '100%', maxHeight: 'calc(100vh - env(safe-area-inset-top) - env(safe-area-inset-bottom))', overflowY: 'auto', borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: '20px 20px max(80px, calc(72px + env(safe-area-inset-bottom)))', boxSizing: 'border-box', borderTop: `1px solid ${C.border}` }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
                <h3 style={{ margin: 0, fontSize: 16, color: '#fff' }}>Notification Settings</h3>
                <button onClick={() => setNotifModal(false)} style={{ background: 'none', border: 'none', color: '#888', cursor: 'pointer' }}><X size={20} /></button>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 14, marginBottom: 20 }}>
                {[
                  { key: 'reminders', title: 'Daily Reminders', desc: 'Alerts to log meals and track nutrition goals.' },
                  { key: 'alerts', title: 'Health Alerts', desc: 'Critical notifications about allergens or health grade warnings.' },
                  { key: 'weekly', title: 'Weekly Reports', desc: 'Receive weekly progress reports in your email.' }
                ].map(item => (
                  <div key={item.key} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 14px', borderRadius: 12, background: 'rgba(255,255,255,0.02)', border: `1px solid ${C.border}` }}>
                    <div style={{ flex: 1, paddingRight: 12 }}>
                      <span style={{ fontSize: 14, color: '#fff', fontWeight: 600, display: 'block' }}>{item.title}</span>
                      <span style={{ fontSize: 11, color: C.muted2, display: 'block', marginTop: 2 }}>{item.desc}</span>
                    </div>
                    <Toggle on={notifs[item.key]} onToggle={() => setNotifs(prev => ({ ...prev, [item.key]: !prev[item.key] }))} />
                  </div>
                ))}
              </div>

              <BtnOrange onClick={() => setNotifModal(false)}>Save Preferences</BtnOrange>
            </div>
          </div>
        )}

        {/* ════════════════════════════════════════════════════
            MODAL 3: CHANGE PASSWORD (SETTINGS GEAR)
            ════════════════════════════════════════════════════ */}
        {pwdModal && (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', zIndex: 2100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 'env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)' }}>
            <div style={{ background: '#171a20', width: '100%', maxWidth: 360, maxHeight: 'calc(100vh - env(safe-area-inset-top) - env(safe-area-inset-bottom) - 40px)', overflowY: 'auto', borderRadius: 16, padding: 20, boxSizing: 'border-box', border: `1px solid ${C.border}` }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                <h3 style={{ margin: 0, fontSize: 16, color: '#fff', display: 'flex', alignItems: 'center', gap: 6 }}>
                  <Key size={18} color={C.orange} /> Security
                </h3>
                <button onClick={() => { setPwdModal(false); setPwdToast(null); }} style={{ background: 'none', border: 'none', color: '#888', cursor: 'pointer' }}><X size={20} /></button>
              </div>

              {pwdToast && (
                <div style={{
                  display: 'flex', alignItems: 'center', gap: 8, padding: '10px 12px', borderRadius: 8, marginBottom: 14,
                  background: pwdToast.type === 'success' ? 'rgba(34,197,94,0.1)' : 'rgba(255,77,109,0.1)',
                  border: `1px solid ${pwdToast.type === 'success' ? 'rgba(34,197,94,0.3)' : 'rgba(255,77,109,0.3)'}`,
                  color: pwdToast.type === 'success' ? '#4ade80' : '#ff4d6d', fontSize: 12, fontWeight: 500
                }}>
                  {pwdToast.type === 'success' ? <Check size={14} /> : <ShieldAlert size={14} />}
                  {pwdToast.msg}
                </div>
              )}
              <form onSubmit={handlePasswordChange} style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                <div>
                  <label style={{ fontSize: 11, color: C.muted, fontWeight: 600, display: 'block', marginBottom: 5 }}>CURRENT PASSWORD</label>
                  <input 
                    type="password" 
                    value={pwdForm.current}
                    onChange={e => setPwdForm({ ...pwdForm, current: e.target.value })}
                    style={{ width: '100%', padding: '12px 14px', background: C.input, border: `1px solid ${C.inputB}`, borderRadius: 10, color: C.text, fontSize: 13, outline: 'none', boxSizing: 'border-box' }} 
                  />
                </div>

                <div>
                  <label style={{ fontSize: 11, color: C.muted, fontWeight: 600, display: 'block', marginBottom: 5 }}>NEW PASSWORD</label>
                  <input 
                    type="password" 
                    value={pwdForm.new}
                    onChange={e => setPwdForm({ ...pwdForm, new: e.target.value })}
                    style={{ width: '100%', padding: '12px 14px', background: C.input, border: `1px solid ${C.inputB}`, borderRadius: 10, color: C.text, fontSize: 13, outline: 'none', boxSizing: 'border-box' }} 
                  />
                </div>

                <div>
                  <label style={{ fontSize: 11, color: C.muted, fontWeight: 600, display: 'block', marginBottom: 5 }}>CONFIRM NEW PASSWORD</label>
                  <input 
                    type="password" 
                    value={pwdForm.confirm}
                    onChange={e => setPwdForm({ ...pwdForm, confirm: e.target.value })}
                    style={{ width: '100%', padding: '12px 14px', background: C.input, border: `1px solid ${C.inputB}`, borderRadius: 10, color: C.text, fontSize: 13, outline: 'none', boxSizing: 'border-box' }} 
                  />
                </div>

                <div style={{ marginTop: 8 }}>
                  <BtnOrange type="submit" disabled={pwdLoading}>
                    {pwdLoading ? 'Updating...' : 'Update Password'}
                  </BtnOrange>
                </div>
              </form>
            </div>
          </div>
        )}

      </div>
    </AppLayout>
  );
}
